{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Sertraline, which shares the chlorophenyl-cyclohexane lipophilic motif, had an estimated absolute oral bioavailability of 62% (Fmax 0.639) in healthy subjects, supporting F ≥20% for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Thalidomide, a non-ionizable lipophilic aromatic drug, showed extensive oral absorption with estimated bioavailability of 80-100%, supporting high F for lipophilic non-ionizable molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Bepotastine, a chlorophenyl-containing drug, exhibited >80% oral absorption in humans, supporting high F for chlorophenyl lipophilic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiludronate had absolute F of 6% (2-11%), but this low value is tied to its bisphosphonate polar character, which is absent in the query; low transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Danavorexton had poor oral bioavailability requiring IV infusion, but its polar carbamate/sulfonamide groups are not present in the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic naphthoquinone with a chlorophenyl-cyclohexane substituent. The most transferable analogues (sertraline, thalidomide, bepotastine) demonstrate F >20% for lipophilic, non-ionizable or chlorophenyl-containing drugs. The low-F analogues (tiludronate, danavorexton) owe their poor absorption to polar ionizable groups absent in the query. Under a high-fat fed state, solubility-limited absorption is expected to be enhanced, supporting F ≥20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for the query molecule; all evidence molecules have low Morgan similarity (<0.26).",
    "Most evidence records do not specify high-fat fed conditions; the food effect is inferred from lipophilicity and the fed-state condition.",
    "Conflicting sertraline bioavailability values (9-95%) introduce uncertainty, though most absolute estimates exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

